import { test } from "node:test";
import assert from "node:assert/strict";
import { shippingFee } from "../src/pricing.ts";

const apple = (qty: number) => ({ sku: "apple" as const, price: 1, qty });
const pear = (qty: number) => ({ sku: "pear" as const, price: 2, qty });

test("shipping is free when total is $50 or more", () => {
  // total: 50 apples at 1 = 50
  assert.equal(shippingFee([apple(50)]), 0);
  // total: 51 apples at 1 = 51 (>=50)
  assert.equal(shippingFee([apple(51)]), 0);
  // total: 25 pears at 2 = 50
  assert.equal(shippingFee([pear(25)]), 0);
  // mix: 24 pears (48) + 2 apples (2) = 50
  assert.equal(shippingFee([pear(24), apple(2)]), 0);
});

test("shipping unchanged when total is less than $50", () => {
  // non-empty cart, total < 50: should be 5 as before
  assert.equal(shippingFee([apple(1)]), 5);
  assert.equal(shippingFee([apple(10)]), 5);
  assert.equal(shippingFee([apple(49)]), 5);
  assert.equal(shippingFee([pear(24)]), 5);
  // empty cart remains 0
  assert.equal(shippingFee([]), 0);
});
TS
echo "done"

